import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import"./chunks/assets.B25yjHWQ.js";var i=JSON.parse(`{"title":"搭建VUEPRSS文档+Github+腾讯云EdgeOne","description":"","frontmatter":{"title":"搭建VUEPRSS文档+Github+腾讯云EdgeOne","sidebarTitle":"博客搭建全流程","date":"2026-04-06T00:00:00.000Z","category":"随笔","tags":["建站笔记"]},"headers":[],"relativePath":"articles/notes/website/hellovuepress.md","filePath":"articles/notes/website/hellovuepress.md","articleMeta":{"updated":"2026-04-06","words":1025,"minutes":3}}`),a={name:`articles/notes/website/hellovuepress.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>本教程以自用为主，使用的是基于Vuepress的plume主题。预览网站：<a href="https://yunriver.com" target="_blank" rel="noreferrer">yunriver.com</a></p><h2 id="本地安装" tabindex="-1">本地安装 <a class="header-anchor" href="#本地安装" aria-label="Permalink to “本地安装”">​</a></h2><p>安装教程详见<a href="https://theme-plume.vuejs.press/guide/usage/" target="_blank" rel="noreferrer">官方文档</a>，以pnpm为例，在本地运行以下命令：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vuepress-theme-plume@latest</span></span></code></pre></div><p>本地调试：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pnpm run docs:dev</span></span></code></pre></div><h2 id="设立专题-集合" tabindex="-1">设立专题/集合 <a class="header-anchor" href="#设立专题-集合" aria-label="Permalink to “设立专题/集合”">​</a></h2><p>plume主题支持集合的概念，即一个项目下可以有多个子文档库，子文档库之间使用独立的导航栏。</p><p>集合有两种类型，分别是post类型和doc类型。post类型实现博客功能，doc类型实现文档库功能、带有侧边栏。</p><p>打开 <code>.vuepress/collections.ts</code> 文件，以设置“生活记”、“投资记”、“健康记”三个专题为例，修改代码如下：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import { defineCollection, defineCollections } from &#39;vuepress-theme-plume&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//const blog = defineCollection({</span></span>
<span class="line"><span>  // post 类型，这里用于实现 博客功能</span></span>
<span class="line"><span>  //type: &#39;post&#39;,</span></span>
<span class="line"><span>  // 文档集合所在目录，相对于 \`docs\`</span></span>
<span class="line"><span>  //dir: &#39;blog&#39;,</span></span>
<span class="line"><span>  // 文档标题，它将用于在页面的面包屑导航中显示</span></span>
<span class="line"><span>  //title: &#39;Blog&#39;,</span></span>
<span class="line"><span>  // 文章列表页的链接，如果 \`linkPrefix\` 未定义，它也将作为 相关的文章的</span><span> //permalink 的前缀</span></span>
<span class="line"><span>  //link: &#39;/blog/&#39;,</span></span>
<span class="line"><span>  //   linkPrefix: &#39;/article/&#39;,</span><span> // 相关文章的链接前缀</span></span>
<span class="line"><span>  //   postList: true,</span><span> // 是否启用文章列表页</span></span>
<span class="line"><span>  //   tags: true,</span><span> // 是否启用标签页</span></span>
<span class="line"><span>  //   archives: true,</span><span> // 是否启用归档页</span></span>
<span class="line"><span>  //   categories: true,</span><span> // 是否启用分类页</span></span>
<span class="line"><span>  //   postCover: &#39;right&#39;,</span><span> // 文章封面位置</span></span>
<span class="line"><span>  //   pagination: 15,</span><span> // 每页显示文章数量</span></span>
<span class="line"><span>//})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const lifeDoc = defineCollection({</span></span>
<span class="line"><span>  // doc 类型，该类型带有侧边栏</span></span>
<span class="line"><span>  type: &#39;doc&#39;,</span></span>
<span class="line"><span>  // 文档集合所在目录，相对于 \`docs\`</span></span>
<span class="line"><span>  dir: &#39;lifedoc&#39;,</span></span>
<span class="line"><span>  // \`dir\` 所指向的目录中的所有 markdown 文件，其 permalink 需要以 \`linkPrefix\` 配置作为前缀</span></span>
<span class="line"><span>  // 如果 前缀不一致，则无法生成侧边栏。</span></span>
<span class="line"><span>  // 所以请确保  markdown 文件的 permalink 都以 \`linkPrefix\` 开头</span></span>
<span class="line"><span>  linkPrefix: &#39;/lifedoc&#39;,</span></span>
<span class="line"><span>  // 文档标题，它将用于在页面的面包屑导航中显示</span></span>
<span class="line"><span>  title: &#39;生活记&#39;,</span></span>
<span class="line"><span>  // 手动配置侧边栏结构</span></span>
<span class="line"><span>  //sidebar: [&#39;&#39;, &#39;foo&#39;, &#39;bar&#39;],</span></span>
<span class="line"><span>  // 根据文件结构自动生成侧边栏</span></span>
<span class="line"><span>  sidebar: &#39;auto&#39;,</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const investDoc = defineCollection({</span></span>
<span class="line"><span>  // doc 类型，该类型带有侧边栏</span></span>
<span class="line"><span>  type: &#39;doc&#39;,</span></span>
<span class="line"><span>  // 文档集合所在目录，相对于 \`docs\`</span></span>
<span class="line"><span>  dir: &#39;invest&#39;,</span></span>
<span class="line"><span>  // \`dir\` 所指向的目录中的所有 markdown 文件，其 permalink 需要以 \`linkPrefix\` 配置作为前缀</span></span>
<span class="line"><span>  // 如果 前缀不一致，则无法生成侧边栏。</span></span>
<span class="line"><span>  // 所以请确保  markdown 文件的 permalink 都以 \`linkPrefix\` 开头</span></span>
<span class="line"><span>  linkPrefix: &#39;/invest&#39;,</span></span>
<span class="line"><span>  // 文档标题，它将用于在页面的面包屑导航中显示</span></span>
<span class="line"><span>  title: &#39;投资记&#39;,</span></span>
<span class="line"><span>  // 手动配置侧边栏结构</span></span>
<span class="line"><span>  //sidebar: [&#39;&#39;, &#39;foo&#39;, &#39;bar&#39;],</span></span>
<span class="line"><span>  // 根据文件结构自动生成侧边栏</span></span>
<span class="line"><span>  sidebar: &#39;auto&#39;,</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const health = defineCollection({</span></span>
<span class="line"><span>  // doc 类型，该类型带有侧边栏</span></span>
<span class="line"><span>  type: &#39;doc&#39;,</span></span>
<span class="line"><span>  // 文档集合所在目录，相对于 \`docs\`</span></span>
<span class="line"><span>  dir: &#39;health&#39;,</span></span>
<span class="line"><span>  // \`dir\` 所指向的目录中的所有 markdown 文件，其 permalink 需要以 \`linkPrefix\` 配置作为前缀</span></span>
<span class="line"><span>  // 如果 前缀不一致，则无法生成侧边栏。</span></span>
<span class="line"><span>  // 所以请确保  markdown 文件的 permalink 都以 \`linkPrefix\` 开头</span></span>
<span class="line"><span>  linkPrefix: &#39;/health&#39;,</span></span>
<span class="line"><span>  // 文档标题，它将用于在页面的面包屑导航中显示</span></span>
<span class="line"><span>  title: &#39;健身记&#39;,</span></span>
<span class="line"><span>  // 手动配置侧边栏结构</span></span>
<span class="line"><span>  //sidebar: [&#39;&#39;, &#39;foo&#39;, &#39;bar&#39;],</span></span>
<span class="line"><span>  // 根据文件结构自动生成侧边栏</span></span>
<span class="line"><span>  sidebar: &#39;auto&#39;,</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/**</span></span>
<span class="line"><span> * 导出所有的 collections</span></span>
<span class="line"><span> * (blog 为博客示例，如果不需要博客功能，请删除)</span></span>
<span class="line"><span> * (demoDoc 为参考示例，如果不需要它，请删除)</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>export default defineCollections([</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//blog</span></span>
<span class="line"><span>lifeDoc,</span></span>
<span class="line"><span>investDoc,</span></span>
<span class="line"><span>health,</span></span>
<span class="line"><span>])</span></span></code></pre></div><p>上述三个专题的对应访问页面分别是</p><p><code>https://你的域名/lifedoc</code></p><p><code>https://你的域名/invest</code></p><p><code>https://你的域名/health</code></p><h2 id="个性化配置" tabindex="-1">个性化配置 <a class="header-anchor" href="#个性化配置" aria-label="Permalink to “个性化配置”">​</a></h2><p>打开 <code>.vuepress/config.ts</code> 文件，取消对应功能的注释，实现主题的各类功能，包括：自动添加 frontmatter 配置、启用嵌入 bilibili视频 语法 @<a href="./bid.html">bilibili</a>、启用数学公式、启用图片懒加载等功能。</p><h2 id="内容写作" tabindex="-1">内容写作 <a class="header-anchor" href="#内容写作" aria-label="Permalink to “内容写作”">​</a></h2><p>在部署之后，后续只需要使用Typora等Markdown编辑器，撰写文档内容，专注写作。</p><p>markdown文件存放在/docs目录下的对应专题文件夹，图片可以通过Typora的自动复制图片至指定目录的功能，全部存放于docs/.vuepress/public目录下，集中统一管理。</p><p>markdown文件的YAML参考如下：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>title: 文章标题</span></span>
<span class="line"><span>createTime: 2026/03/11 10:53:30</span></span>
<span class="line"><span>permalink: /专题名字/xx/xxxx/</span></span></code></pre></div><p>文档结构如下：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>├── docs</span></span>
<span class="line"><span>│   ├── 专题1</span></span>
<span class="line"><span>│   │   ├── 示例1.md</span></span>
<span class="line"><span>│   │   └── 示例2.md</span></span>
<span class="line"><span>│   ├── 专题2</span></span>
<span class="line"><span>│   │   ├── 示例3.md</span></span>
<span class="line"><span>│   └── README.md</span></span></code></pre></div><h2 id="托管至github仓库" tabindex="-1">托管至GitHub仓库 <a class="header-anchor" href="#托管至github仓库" aria-label="Permalink to “托管至GitHub仓库”">​</a></h2><p>通过Github Desktop或者其他Git工具，将本地文件PUSH到Github的仓库中。</p><h2 id="部署到腾讯云edgeone" tabindex="-1">部署到腾讯云EdgeOne <a class="header-anchor" href="#部署到腾讯云edgeone" aria-label="Permalink to “部署到腾讯云EdgeOne”">​</a></h2><p>对于备案域名，使用腾讯云EdgeOne部署能够带来不错的访问体验。</p><p><img src="/images/image-20260406200641240.png" alt="image-20260406200641240" width="1824" height="978"></p><p>选择导入Git仓库。</p><p>构建设置填写如下方案：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>框架预设 Other</span></span>
<span class="line"><span></span></span>
<span class="line"><span>根目录 ./</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出目录 docs/.vuepress/dist</span></span>
<span class="line"><span></span></span>
<span class="line"><span>编译命令 npm run docs:build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>安装命令 npm install</span></span></code></pre></div><p>开始部署即可。</p><h2 id="可选-接入waline评论" tabindex="-1">可选：接入Waline评论 <a class="header-anchor" href="#可选-接入waline评论" aria-label="Permalink to “可选：接入Waline评论”">​</a></h2><p>在VUEPRESS根目录安装Waline前端，运行如下命令：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pnpm add -D @waline/client</span></span></code></pre></div><p>再打开 <code>.vuepress/config.ts</code> 文件，在 <code>plumeTheme</code> 的配置对象中加入 <code>plugins.comment</code> 模块。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import { defineUserConfig } from &#39;vuepress&#39;</span></span>
<span class="line"><span>import { plumeTheme } from &#39;vuepress-theme-plume&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export default defineUserConfig({</span></span>
<span class="line"><span>  theme: plumeTheme({</span></span>
<span class="line"><span>    // 其他的主题配置...</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    plugins: {</span></span>
<span class="line"><span>      comment: {</span></span>
<span class="line"><span>        provider: &#39;Waline&#39;, // 指定服务提供商为 Waline</span></span>
<span class="line"><span>        comment: true, // 全局默认开启评论</span></span>
<span class="line"><span>        serverURL: &#39;https://你的Waline后端地址&#39;, // 填写你现有的 Waline 后端 URL</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        // 以下是 Waline 的可选扩展配置：</span></span>
<span class="line"><span>        // dark: &#39;html.dark&#39;,</span><span> // 适配 Plume 主题的夜间模式</span></span>
<span class="line"><span>        // emoji: [&#39;https://unpkg.com/@waline/emojis@1.1.0/weibo&#39;],</span><span> // 自定义表情包</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  })</span></span>
<span class="line"><span>})</span></span></code></pre></div>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};